import * as T from './assets/three.js';
// Dedicated 30g soft tube: circular cap -> rounded shoulder -> flattened, ribbed heat seal.
const profile=[[.535,.414,.333],[.56,.426,.34],[.62,.435,.342],[.9,.452,.334],[1.3,.489,.305],[1.8,.54,.254],[2.25,.595,.195],[2.62,.64,.12],[2.82,.678,.065],[2.86,.687,.046],[2.88,.69,.038]];
function section(y){for(let i=1;i<profile.length;i++)if(y<=profile[i][0]){const a=profile[i-1],b=profile[i],t=T.MathUtils.clamp((y-a[0])/(b[0]-a[0]),0,1);return [T.MathUtils.lerp(a[1],b[1],t),T.MathUtils.lerp(a[2],b[2],t)]}return profile.at(-1).slice(1)}
function tubeGeometry(){const p=[],uv=[],idx=[],steps=100,n=128;for(let j=0;j<=steps;j++){const y=T.MathUtils.lerp(profile[0][0],profile.at(-1)[0],j/steps),[rx,rz]=section(y);for(let i=0;i<=n;i++){const angle=i/n*Math.PI*2;p.push(rx*Math.sin(angle),y,rz*Math.cos(angle));uv.push(i/n,j/steps)}}for(let j=0;j<steps;j++)for(let i=0;i<n;i++){const a=j*(n+1)+i,b=a+1,c=a+n+1,d=c+1;idx.push(a,b,c,b,d,c)}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return g}
function capGeometry(){const pts=[new T.Vector2(0,0),new T.Vector2(.385,0),new T.Vector2(.4,.007),new T.Vector2(.412,.022),new T.Vector2(.416,.045),new T.Vector2(.43,.52),new T.Vector2(.427,.541),new T.Vector2(.409,.549),new T.Vector2(0,.549)];return new T.LatheGeometry(pts,128)}
function printing(){const c=document.createElement('canvas');c.width=768;c.height=2048;const ctx=c.getContext('2d');ctx.translate(384,1024);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#56666b';for(const [text,font,y]of [['LANEIGE',154,-200],['WATER BANK BLUE HYALURONIC',107,0],['CLEANSING FOAM',102,200]]){ctx.font=font+'px Arial';ctx.fillText(text,0,y,1860)}const map=new T.CanvasTexture(c);map.colorSpace=T.SRGBColorSpace;map.anisotropy=8;const p=[],uv=[],idx=[],cols=16,rows=72,width=.43,y0=.99,h=1.32;for(let j=0;j<=rows;j++){const y=y0+j/rows*h,[rx,rz]=section(y);for(let i=0;i<=cols;i++){const x=(i/cols-.5)*width,z=rz*Math.sqrt(Math.max(0,1-(x/rx)**2))+.001;p.push(x,y,z);uv.push(i/cols,j/rows)}}for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){const a=j*(cols+1)+i,b=a+1,d=a+cols+1;idx.push(a,b,d,b,d+1,d)}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return new T.Mesh(g,new T.MeshBasicMaterial({map,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1}))}
export function createFoamStructure(){const root=new T.Group();root.name='「小蓝盾」洁颜膏 · 30g';const bodyMat=new T.MeshPhysicalMaterial({color:0xa6d2df,metalness:0,roughness:.31,clearcoat:.75,clearcoatRoughness:.22,ior:1.47,envMapIntensity:.9});const capMat=new T.MeshPhysicalMaterial({color:0x99c4d3,metalness:0,roughness:.34,clearcoat:.5,clearcoatRoughness:.24});const body=new T.Mesh(tubeGeometry(),bodyMat);body.name='由圆肩过渡到扁平封口的软管';root.add(body);const cap=new T.Mesh(capGeometry(),capMat);cap.name='独立闭合圆盖';root.add(cap);const seam=new T.Mesh(new T.TorusGeometry(.423,.006,8,128),new T.MeshStandardMaterial({color:0x79a8b8,roughness:.4}));seam.rotation.x=Math.PI/2;seam.position.y=.548;seam.name='盖肩分界细缝';root.add(seam);
const seal=new T.Mesh(new T.BoxGeometry(1.38,.12,.076,1,1,1),bodyMat);seal.position.y=2.94;seal.name='顶部热封压边';root.add(seal);const ribGeometry=new T.BoxGeometry(.008,.115,.006),ribMat=bodyMat.clone();ribMat.roughness=.4;for(let i=0;i<105;i++){const x=-.678+i*.013;for(const sign of [-1,1]){const rib=new T.Mesh(ribGeometry,ribMat);rib.position.set(x,2.94,sign*.041);rib.name='热封竖向细纹';root.add(rib)}}
const border=new T.Mesh(new T.BoxGeometry(1.37,.014,.085),capMat);border.position.y=2.88;border.name='封口压边横线';root.add(border);root.traverse(n=>{if(n.isMesh){n.castShadow=true;n.receiveShadow=true}});root.userData={buildMethod:'researched-water-bank-foam-30g',productKey:'water-bank-foam-30g',unknownFaces:['30g背面文字','开盖喷嘴与铰链','精确毫米尺寸'],referenceBasis:'用户30g主图 + 兰芝香港30g套装图（字样排版不同，仅交叉核对结构）+ 美国150g材质图（容量不同）'};return root}

export async function createWaterBankFoam(){const root=createFoamStructure(),label=printing();label.name='按用户图竖排的正面独立印刷';label.userData.noCastShadow=true;root.add(label);return root}
